import { esc, icon } from '../ui.js';
export const activityTypes=['פגישה','פגישת זום','שיחת ועידה','שיחת טלפון'];
export const activityStatuses=['בוטלה','בוצעה','נדחתה','נקבעה'];
export const localDate=value=>value?new Date(value).toLocaleString('he-IL',{dateStyle:'short',timeStyle:'short'}):'—';
export function nativePager(total,ui,prefix) {
 const size=ui[prefix+'Size']||10,pages=Math.max(1,Math.ceil(total/size));
 ui[prefix+'Page']=Math.min(ui[prefix+'Page']||1,pages);
 return `<div class="pager native-pager"><div class="page-sizes" aria-label="רשומות בעמוד">${[10,25,50,100].map(n=>`<button data-action="native-size" data-prefix="${prefix}" data-size="${n}" aria-pressed="${size===n}">${n}</button>`).join('')}</div><div class="page-numbers"><button aria-label="העמוד הקודם" data-action="native-page" data-prefix="${prefix}" data-step="-1" ${ui[prefix+'Page']===1?'disabled':''}>«</button><span>${ui[prefix+'Page']}</span><button aria-label="העמוד הבא" data-action="native-page" data-prefix="${prefix}" data-step="1" ${ui[prefix+'Page']===pages?'disabled':''}>»</button></div><span>מספר רשומות: <b>${total}</b></span></div>`;
}
export default function activity({state,ui}) {
 const f=ui.activityFilters||{};
 const all=state.activityRecords.filter(r=>(!f.title||r.title.includes(f.title))&&(!f.customer||(state.records.find(x=>x.id===r.customer)?.name||'').includes(f.customer))&&(!f.type||r.type.includes(f.type))&&(!f.status||r.status.includes(f.status))&&(!f.owner||r.owner.includes(f.owner))&&(!f.from||r.start.slice(0,10)>=f.from)&&(!f.to||r.start.slice(0,10)<=f.to));
 const pager=nativePager(all.length,ui,'activity'),size=ui.activitySize||10,rows=all.slice((ui.activityPage-1)*size,ui.activityPage*size);
 return `<form data-form="activity-search" class="record-search native-search"><details open><summary>חיפוש פעילויות</summary><div class="search-grid">${[['title','כותרת מכילה'],['customer','לקוח מכיל'],['type','סוג מכיל'],['status','סטטוס מכיל'],['owner','אחראי מכיל'],['from','זמן התחלה גדול מ/שווה ל','date'],['to','זמן התחלה קטן מ/שווה ל','date']].map(([key,label,type])=>`<label class="field"><span>${label}</span><input name="${key}" value="${esc(f[key]||'')}" type="${type||'text'}" ${key==='type'||key==='status'?`list="activity-${key}-values"`:''}></label>`).join('')}</div><datalist id="activity-type-values">${activityTypes.map(x=>`<option value="${x}">`).join('')}</datalist><datalist id="activity-status-values">${activityStatuses.map(x=>`<option value="${x}">`).join('')}</datalist></details><div class="search-actions"><button>חפש</button>${Object.values(f).some(Boolean)?'<button type="button" class="quiet" data-action="clear-activity">ניקוי</button>':''}</div></form><section class="record-results activity-results"><div class="table-wrap"><table><thead><tr>${['כותרת','לקוח - שם','אחראי','סוג','סטטוס','זמן התחלה','עריכה',''].map(t=>`<th>${t}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr><td><button class="row-link native-record-link" data-action="edit-activity" data-id="${esc(r.id)}">${icon('calendar')}${esc(r.title)}</button></td><td>${r.customer?`<button class="row-link native-record-link" data-action="edit-record" data-id="${esc(r.customer)}">${icon('building')}${esc(state.records.find(x=>x.id===r.customer)?.name||'—')}</button>`:'—'}</td><td>${esc(r.owner)}</td><td>${esc(r.type)}</td><td>${esc(r.status||'—')}</td><td>${localDate(r.start)}</td><td><div class="row-actions"><button class="edit-icon" data-action="edit-activity" data-id="${esc(r.id)}" aria-label="עריכת ${esc(r.title)}">${icon('edit')}</button><button class="edit-icon delete-icon" data-action="delete-activity" data-id="${esc(r.id)}" aria-label="מחיקת ${esc(r.title)}">×</button><button class="edit-icon" data-action="duplicate-activity" data-id="${esc(r.id)}" aria-label="שכפול ${esc(r.title)}">▢</button></div></td><td></td></tr>`).join('')||'<tr><td colspan="8" class="native-empty">אין פעילויות התואמות לחיפוש</td></tr>'}</tbody></table></div>${pager}</section>`;
}
